import{_ as t,o,c as r,a3 as a}from"./chunks/framework.BWzgKoSO.js";const _=JSON.parse('{"title":"第八部分　安全边界","description":"","frontmatter":{},"headers":[],"relativePath":"ch08-safety.md","filePath":"ch08-safety.md","lastUpdated":1793332176000}'),n={name:"ch08-safety.md"};function s(e,p,l,i,g,h){return o(),r("div",null,[...p[0]||(p[0]=[a('<h1 id="第八部分-安全边界" tabindex="-1">第八部分　安全边界 <a class="header-anchor" href="#第八部分-安全边界" aria-label="Permalink to &quot;第八部分　安全边界&quot;">​</a></h1><p>这一章比前面所有内容都重要。前面讲瘦得漂不漂亮，这一章讲会不会出事。</p><h2 id="_8-1-哪几类人别自己减" tabindex="-1">8.1　哪几类人别自己减 <a class="header-anchor" href="#_8-1-哪几类人别自己减" aria-label="Permalink to &quot;8.1　哪几类人别自己减&quot;">​</a></h2><p>指南写得很明确：孕妇、乳母、老年人，以及患有慢性代谢性疾病的人，应该在医生或营养指导人员指导下科学减重，避免不合理的减重对身体造成损害〔G1，A〕。</p><p>这几类人不等于不能减，是不能照这本书自己减。原因各不一样：</p><p>孕期减重会影响胎儿；哺乳期热量压得太低，奶量和恢复都受影响；老年人本来就容易掉肌肉，再叠一个大缺口，掉的是行走能力；糖尿病人用胰岛素或磺脲类的，少吃一顿可能低血糖。</p><p>还有两类指南没单列，我得加：</p><p><strong>未成年的孩子。</strong> 还在长身体，热量限制会压生长。孩子超重该找儿科或营养门诊，不是照着大人那套算。</p><p><strong>有进食障碍史的人，或者现在就在暴食、催吐的人。</strong> 这一类最要紧。任何“限制吃”的方案对这类人都是火上浇油，越算越糟。这一条后面讲药的时候还会出现一次。</p><p>最后一类：<strong>BMI 正常、只是不满意某个部位的人。</strong> 你需要的不是减重，是抗阻训练和体态。硬减下去，掉的是肌肉。</p><h2 id="_8-2-出现这些信号-先去医院" tabindex="-1">8.2　出现这些信号，先去医院 <a class="header-anchor" href="#_8-2-出现这些信号-先去医院" aria-label="Permalink to &quot;8.2　出现这些信号，先去医院&quot;">​</a></h2><p>我不做诊断，只列信号。出现了，别问网友，去医院。</p><ul><li>月经停了三个月以上</li><li>头发一把一把掉，超过两三个月还在掉</li><li>静息心率明显变快，站起来发晕</li><li>右上腹痛，尤其是吃完油腻以后（胆结石的信号）</li><li>持续便秘或腹泻，两周不好</li><li>情绪一路往下，或者开始控制不住地吃</li><li>体重的下降明显快于计划，人却越来越没劲</li><li>两三个月体重不动，还往上走，同时怕冷、没精神、浮肿</li></ul><p>最后一条对应几件真事：甲状腺功能、正在吃的药、睡眠呼吸暂停，都能让减重卡死。这种事不是你不够努力，是得换科室解决。</p><p><strong>下面这几样不用等，直接去急诊：</strong></p><p>剧烈腹痛并往背后放射（胰腺炎的典型位置）；吐到喝不进水；站起来眼前发黑、心跳到一百二以上；两天没有小便。</p><h2 id="_8-3-司美格鲁肽和替尔泊肽-能不能用" tabindex="-1">8.3　司美格鲁肽和替尔泊肽，能不能用 <a class="header-anchor" href="#_8-3-司美格鲁肽和替尔泊肽-能不能用" aria-label="Permalink to &quot;8.3　司美格鲁肽和替尔泊肽，能不能用&quot;">​</a></h2><p>这一段只讲事实，不给用药建议。要不要用，是你和医生的事。</p><p>先说一句总纲：目前在我国，有五种减重药物获得国家药品监督管理局批准，用于成年原发性肥胖症患者减重〔G9，A〕。下面只说大家问得最多的两种。</p><p><strong>这两样是什么。</strong></p><p>司美格鲁肽的减重版商品名是诺和盈，替尔泊肽是穆峰达。司美格鲁肽作用于 GLP-1 受体，替尔泊肽是 GLP-1 和 GIP 双靶点。共同的路子是：作用于中枢降低饥饿感、增加饱腹感、延缓胃排空，让人吃得少。<strong>它们不是燃脂的。</strong></p><p><strong>时间线</strong>（公开的获批与上市信息）：</p><ul><li>诺和盈：2024 年 6 月 25 日在中国获批减重适应症，2024 年 11 月 17 日上市</li><li>穆峰达：2024 年 5 月先批糖尿病适应症，7 月 19 日批减重，2025 年 1 月 2 日上市</li></ul><p><strong>门槛不一样，这点最容易搞混。</strong></p><p>诺和盈的减重适应症：BMI ≥30，或者 BMI 27 到 30 且有至少一种体重相关合并症。</p><p>穆峰达在中国的减重门槛：BMI ≥28，或者 BMI ≥24 且有合并症。</p><p>也就是说，同一个人可能符合这个、不符合那个。别拿别人的处方给自己用。</p><p><strong>能减多少，口径要说清。</strong></p><p>这里有两组数，混着讲就会失真。</p><p>第一组是试验里的实际减重幅度：STEP-1（68 周）平均减 14.9%〔R13，A〕；SURMOUNT-1（72 周）平均减 15% 到 21%〔R14，A〕。</p><p>第二组是指南里的口径，<strong>去掉安慰剂效应之后</strong>：司美格鲁肽在亚洲人群 68 周减 11.1%；在以中国人为主的人群里，44 周减 8.5%，85% 的受试者减重达到 5% 以上。替尔泊肽 10 到 15 毫克用 12 到 24 个月，去掉安慰剂效应后减 11.9% 到 17.8%；中国人群 11.3% 到 15.1%〔G9，A〕。</p><p>为什么要分两组？因为第一组里有安慰剂组也减掉的那部分——<strong>光是被医生随访、被要求记录饮食，人就会瘦一些。</strong> 报数字不分开说，就是在往自己脸上贴金。</p><p>还有一件事必须一起讲：这些试验里，所有受试者同时都接受了饮食和运动指导。药不是替代那件事，是加上去。</p><p><strong>剂量和&quot;无效就停&quot;。</strong></p><p>司美格鲁肽起始 0.25 毫克每周一次皮下注射，维持剂量 2.4 毫克或 1.7 毫克；替尔泊肽起始 2.5 毫克，最大 15 毫克，都是每周一次〔G9，A〕。</p><p>加量必须按医生给的节奏走，别自己跳。跳剂量换来的不是更快，是吐得更狠。</p><p>指南里还写了一条我觉得很实用的原则：利拉鲁肽用到 16 周，如果体重下降不到基线的 4%，建议停药，因为这类人继续用也很难达到有临床意义的减重〔G9，A〕。换成大白话：<strong>药要有评估点，不能无限期试。</strong></p><p><strong>停药会怎样。</strong></p><p>STEP-1 的延伸研究：在结束 68 周治疗、又停药一年之后，参加延伸研究的 327 人平均减轻了 17.3%，停药后回来的部分是 11.6 公斤，大约三分之二〔R13，B〕。</p><p>SURMOUNT-4：先用 36 周把体重降了 20.9%，然后一半人停药换成安慰剂、一半继续用药，再观察 52 周。结果继续用药的那一半又降了 5.5%，停药那一半回升 14.0%〔R14，B〕。</p><p>指南也写了：停药后会出现不同程度的体重反弹，继续用药体重可进一步下降〔G9，A〕。</p><p>这句话的含义不是&quot;千万别停&quot;，是&quot;把它当一段疗程，不是一次性解决方案&quot;。用之前就得想清楚：停下来之后靠什么撑住。</p><p><strong>禁忌和副作用。</strong></p><p>两种药的禁忌证一致：有甲状腺髓样癌的个人病史或家族史、2 型多发性内分泌腺瘤综合征（MEN2）患者，以及对成分严重过敏的人，禁用〔G9，A〕。</p><p>最常出现的是胃肠道反应：恶心、呕吐、腹泻、便秘、腹痛、消化不良〔G9，A〕。多数集中在加量阶段。少数人出现胰腺炎、胆囊问题。</p><p>还有一条容易漏的：指南专门提到，肌少性肥胖的人用减重药要警惕肌少症加重〔G9，A〕。翻成操作就是——<strong>用药期间更要注意蛋白质和抗阻训练</strong>，不然掉的那部分里肌肉占比会更高。</p><p>还有一条我给不出官方出处，但是常识：这类药必须走正规医院处方，不要在网上、代购渠道买。假药和来源不明的注射剂，风险不在效果，在安全。</p><p><strong>我自己的态度，说一句：</strong></p><p>这东西真实有效，但它解决的是&quot;吃不下&quot;，不解决&quot;不知道怎么吃&quot;。用的人里最后守住体重的，还是那些同时改了吃法和动法的人。</p><p>我不用，不是反对。是我这 78 天想搞清楚的是后者。</p><p>你要是考虑用，去医院找内分泌或营养门诊，把三件事问清楚：我符合哪一档门槛、疗程打算多久、停下来之后怎么办。</p><h2 id="_8-4-一条底线" tabindex="-1">8.4　一条底线 <a class="header-anchor" href="#_8-4-一条底线" aria-label="Permalink to &quot;8.4　一条底线&quot;">​</a></h2><p>这本书里所有数字都是给普通成年人的参考。你不是普通人那一档的时候——怀孕、在吃药、有慢病、年纪大、有进食障碍——这本书能帮你的地方就到这儿了。</p><p>剩下的，交给医生。</p><hr><p>下一部分讲一件更软但同样要紧的事：网上那些说法，怎么自己判断真假。</p>',56)])])}const d=t(n,[["render",s]]);export{_ as __pageData,d as default};
